3. 相关练习
Leetcode上有以下数题与此相关。
3.1 Leetcode 141. Linked List Cycle
Link
Description: Given a linked list, determine if it has a cycle in it.
Floyd's Tortoise and Hare
class Solution {
public:
bool hasCycle(ListNode *head) {
if(!head || !(head->next)) {
return false;
}
ListNode* tortoise = head->next;
ListNode* hare = head->next->next;
while(hare && hare->next) {
if(tortoise == hare) {
return true;
}
tortoise = tortoise->next;
hare = hare->next->next;
}
return false;
}
};
Brent's algorithm
class Solution {
public:
bool hasCycle(ListNode *head) {
if(!head || !(head->next)) {
return false;
}
int current_step = 1;
int limited_step = 1;
ListNode* tortoise = head->next;
ListNode* hare = head->next->next;
while(hare && hare->next) {
if(tortoise == hare) {
return true;
}
if(current_step == limited_step) {
current_step = 0;
limited_step *= 2;
tortoise = hare;
}
hare = hare->next;
current_step++;
}
return false;
}
};
3.2 Leetcode 142. Linked List Cycle II
Link
Description: Given a linked list, return the node where the cycle begins. If there is no cycle, return null.
Floyd's Tortoise and Hare
class Solution {
public:
ListNode *detectCycle(ListNode *head) {
if(!head || !(head->next)) {
return NULL;
}
ListNode* tortoise = head->next;
ListNode* hare = head->next->next;
while(tortoise != hare) {
if(!hare || !(hare->next)) {
return NULL;
}
tortoise = tortoise->next;
hare = hare->next->next;
}
tortoise = head;
while(tortoise != hare) {
tortoise = tortoise->next;
hare = hare->next;
}
return tortoise;
}
};
Brent's algorithm
class Solution {
public:
ListNode *detectCycle(ListNode *head) {
if(!head || !(head->next)) {
return NULL;
}
int current_step = 1;
int limited_step = 1;
ListNode* tortoise = head->next;
ListNode* hare = head->next->next;
while(tortoise != hare) {
if(!hare || !(hare->next)) {
return NULL;
}
if(current_step == limited_step) {
current_step = 0;
limited_step *= 2;
tortoise = hare;
}
hare = hare->next;
current_step++;
}
tortoise = head;
hare = head;
while(current_step--) {
tortoise = tortoise->next;
}
while(tortoise != hare) {
tortoise = tortoise->next;
hare = hare->next;
}
return tortoise;
}
};
3.3 Leetcode 202. Happy Number
Link
Description: Write an algorithm to determine if a number is "happy".
A happy number is a number defined by the following process: Starting with any positive integer, replace the number by the sum of the squares of its digits, and repeat the process until the number equals 1 (where it will stay), or it loops endlessly in a cycle which does not include 1. Those numbers for which this process ends in 1 are happy numbers.
Floyd's Tortoise and Hare
class Solution {
public:
bool isHappy(int n) {
int tortoise = nextNum(n);
int hare = nextNum(nextNum(n));
while(tortoise != hare) {
tortoise = nextNum(tortoise);
hare = nextNum(nextNum(hare));
}
return tortoise == 1;
}
int nextNum(int n) {
int nxt = 0;
while(n) {
int digit = n%10;
nxt += digit*digit;
n /= 10;
}
return nxt;
}
};
Brent's algorithm
class Solution {
public:
bool isHappy(int n) {
int current_step = 1;
int limited_step = 1;
int tortoise = nextNum(n);
int hare = nextNum(nextNum(n));
while(tortoise != hare) {
if(current_step == limited_step) {
current_step = 0;
limited_step *= 2;
tortoise = hare;
}
hare = nextNum(hare);
current_step++;
}
return tortoise == 1;
}
int nextNum(int n) {
int nxt = 0;
while(n) {
int digit = n%10;
nxt += digit*digit;
n /= 10;
}
return nxt;
}
};
3.4 Leetcode 287. Find the Duplicate Number
Link
Given an array nums containing n + 1 integers where each integer is between 1 and n (inclusive), prove that at least one duplicate number must exist. Assume that there is only one duplicate number, find the duplicate one.
Floyd's Tortoise and Hare
class Solution {
private:
vector<int> nums;
public:
int findDuplicate(vector<int>& nums) {
if(nums.empty()) {
return -1;
}
this->nums = nums;
int tortoise = f(nums[0]);
int hare = f(f(nums[0]));
while(tortoise != hare) {
tortoise = f(tortoise);
hare = f(f(hare));
}
tortoise = nums[0];
while(tortoise != hare) {
tortoise = f(tortoise);
hare = f(hare);
}
return tortoise;
}
int f(int n) {
return nums[n];
}
};
Brent's algorithm
class Solution {
private:
vector<int> nums;
public:
int findDuplicate(vector<int>& nums) {
if(nums.empty()) {
return -1;
}
this->nums = nums;
int current_step = 1;
int limited_step = 1;
int tortoise = f(nums[0]);
int hare = f(f(nums[0]));
while(tortoise != hare) {
if(current_step == limited_step) {
current_step = 0;
limited_step *= 2;
tortoise = hare;
}
hare = f(hare);
current_step++;
}
tortoise = nums[0];
hare = nums[0];
while(current_step--) {
tortoise = f(tortoise);
}
while(tortoise != hare) {
tortoise = f(tortoise);
hare = f(hare);
}
return tortoise;
}
int f(int n) {
return nums[n];
}
};
4. 实际应用
环检测(cycle detection)问题的实际应用有 伪随机数生成器(pseudorandom number generators)强度的度量，比如 线性同余生成器(linear congruential generator)，加密哈希函数的冲突检测，细胞自动机(cellular automaton)的振荡周期配置等

1. vector
1.1 erase
以前用vector时只是使用push_back(),pop_back(),begin(),end(),front(),back()等，没用过erase(), 今天搭配iterator用了一下, 才发现很神奇。比如删除一个vector上指定值为val的元素:
for(vector<int>::iterator it = nums.begin(); it != nums.end(); ) {
if( nums[i] == val ) {
nums.erase(it++);
} else {
it++;
}
}
上面这段代码是错误的，而且只要改一处就可以正确。修改后为:
for(vector<int>::iterator it = nums.begin(); it != nums.end(); ) {
if( nums[i] == val ) {
nums.erase(it);
} else {
it++;
}
}
区别就是erase之后it没有自增，也就是将nums某个元素erase之后，并不需要将iterator自增，nums会自动调整整个结构，将后一个元素放到当前指针指的位置。
1.2 iterator
iterator某种程度上可以当作指针来使用，上述程序还可以这样:
while( it != nums.end() ) {
if( *it == val ) {
nums.erase(it);
} else {
it++;
}
}
1.3 初始化
我通常不初始化vector, 但如果需要初始化分配一定空间, 可以使用vector<int> num(100); vector<int> num(100,0)，前者是包含100个值默认初始化值的元素，后者是包含100个0。
此外，C++11新增了一个array类，是固定长度的数组，使用起来可能更方便和安全，有兴趣可以再仔细看下。
2. GCC编译器的问题
在CodeBlocks里输入vector<vector<int>> s竟然会编译出错，'>>' should be '> >' within a nested template argument list，改成 vector< vector<int> > s才好, 而在VS里并没有问题, CodeBlocks自带的MinGW中的GCC编译器在某些方面还是比不上VS的编译器的
3. Console输入
C++中输入字符串我一般常用string str; cin >> str;，然而今天要输入一个字符串，中间带有空格，发现上述写法不对，会自动滤除所有空格，搜了下，使用getline(cin,str);即可。
4. Struct与Class
struct与class在C++者两者基本相同, 区别仅在以下几点:
struct的成员默认权限是public，而class的成员默认权限是private
struct的默认继承方式为public，而class的默认继承为private
只有class可用模板template定义参数，而struct不可以
5. 关于sizeof
首先声明: sizeof不是函数,是操作符
sizeof是C/C++中的一个操作符(operator)，其作用就是返回一个对象或者类型所占的内存字节数
sizeof的计算发生在编译时刻，所以它可以被当作常量表达式使用
指针记录了另一个对象的地址，既然是来存放地址的，那么必然等于计算机内部地址总线的宽度，所以在32位计算机中，一个指针变量的返回值是4字节，在64位系统中指针变量的sizeof结果为8，当然与编译器的版本有关，如果在64位系统上运行32位编译器自然还是4。注意sizeof(NULL) = 4
数组的sizeof值等于数组所占用的内存字节数
每个类的实例，在内存中都有一个独一无二的地址，为了达到这个目的，编译器往往会给一个空类隐含的加一个字节，这样空类在实例化后在内存得到了独一无二的地址，因此空类默认会占用1个字节。如：
class a {};
sizeof(a);      //为1

